    for _ in range(4):
        _Ph = _bd_rng.standard_normal(_n_t)
        _lhs = float(_Ph @ (_Mi_t @ _Mi_t) @ _Ph)
        _rhs = float(np.linalg.norm(_Mi_t @ _Ph) ** 2)
        _bd_max_tel = max(_bd_max_tel, abs(_lhs - _rhs) / max(abs(_rhs), 1e-30))
