    _ev = np.sort(np.linalg.eigvalsh(_Q.conj().T @ _H @ _Q))
    _evf, _Vf = np.linalg.eigh(_H)
    _pm2 = [_Vf[:, _i] for _i in range(10) if abs(_evf[_i] - 2) < 1e-8 or abs(_evf[_i] + 2) < 1e-8]
    _ovl = max(float(np.linalg.norm(_G.T @ _v)) for _v in _pm2)
