p06_cols = lambda lam: [sum(1 for r in lam if r > j) for j in range(lam[0])]
assert not all(v % 2 == 0 for v in p06_cols((2,2,2)))
assert not all(v % 2 == 0 for v in p06_cols((2,1,1,1,1)))
