def p08_dim(lam, n=11):
    if len(lam) > n: return 0
    cols = [sum(1 for r in lam if r > j) for j in range(lam[0])] if lam else []
    num = den = 1
    for i, l in enumerate(lam):
        for j in range(l):
            num *= (n + j - i)
            den *= (l - j) + cols[j] - i - 1
    assert num % den == 0
    return num // den

