def _p30_eig(kf):
    s = p30_phi ** kf
    w = [p30_math.exp(-d / s) for d in range(6)]
    return [w[0] + sum(2 * w[d] * p30_math.cos(2 * p30_math.pi * m * d / 11)
                       for d in range(1, 6)) for m in range(11)]

